<script setup>
import {computed, ref, watch} from 'vue';
const props=defineProps({record:{type:Object,required:true}});
defineEmits(['close']);
const tab=ref('fields'),page=ref(1),pageSize=ref(10);
const report=computed(()=>props.record.report);
const passed=computed(()=>props.record.passed ?? report.value.status==='pass');
const fields=computed(()=>report.value.fields.filter(f=>f.status!=='pass'));
const issueCount=computed(()=>report.value.counts.issue||0);
const manualCount=computed(()=>report.value.counts.manual||0);
const uncheckedCount=computed(()=>report.value.counts.not_checked||0);
const conclusionDetail=computed(()=>{
  const parts=[];
  if(issueCount.value)parts.push(`${issueCount.value} 项字段规则不符`);
  if(report.value.differences.length)parts.push(`${report.value.differences.length} 处固定条款差异`);
  if(manualCount.value)parts.push(`${manualCount.value} 项需人工判断`);
  if(uncheckedCount.value)parts.push(`${uncheckedCount.value} 项未能检查`);
  return parts.length?parts.join('，'):'本次已配置的规则均通过';
});
const rows=computed(()=>tab.value==='fields'?fields.value:report.value.differences);
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/pageSize.value)));
const visible=computed(()=>rows.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const labels={manual:'需人工判断',issue:'规则不符',not_checked:'未能检查'};
const conclusionLabels={pass:'符合已配置规则',needs_changes:'需修改',needs_review:'需人工确认',incomplete:'检查不完整'};
const date=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
watch([tab,pageSize,()=>props.record.id],()=>page.value=1);
</script>
<template>
<section class="check-report">
  <div class="report-heading"><div><span class="report-eyebrow">模板校验 / 结果报告</span><h1>模板核验报告</h1><p class="report-subject">{{record.filename}}</p><p class="report-meta">基准模板：{{record.template_name}} · 发布版本 V{{record.version}} · 校验于 {{date(record.created_at)}}</p></div><div class="report-heading-actions"><RouterLink to="/validation-records" class="button">核验记录</RouterLink><button class="button" @click="$emit('close')">返回</button></div></div>
  <div class="report-banner" :class="passed?'pass':'attention'"><span aria-hidden="true">{{passed?'✓':'!'}}</span><div><small>本次结论</small><h2>{{conclusionLabels[report.status] || '需进一步处理'}}</h2><p>{{conclusionDetail}}。请查看下方具体原因，计算结果已自动保存。</p></div></div>
  <div class="report-stats"><div><span>校验字段</span><strong>{{report.counts.total}}</strong></div><div class="is-pass"><span>字段通过</span><strong>{{report.counts.pass}}</strong></div><div :class="{'is-issue':fields.length}"><span>需处理字段</span><strong>{{fields.length}}</strong></div><div><span>固定条款差异</span><strong>{{report.counts.differences}}</strong></div></div>
  <div class="report-card">
    <nav class="report-tabs" aria-label="核验报告分类"><button :class="{active:tab==='fields'}" @click="tab='fields'">需处理字段 <b>{{fields.length}}</b></button><button :class="{active:tab==='differences'}" @click="tab='differences'">固定条款差异 <b>{{report.differences.length}}</b></button></nav>
    <div v-if="tab==='fields'&&rows.length" class="report-table-wrap"><table><thead><tr><th>字段</th><th>内容对照</th><th>核验结果与原因</th></tr></thead><tbody><tr v-for="f in visible" :key="f.id"><td class="report-field-name">{{f.name}}</td><td><div class="report-comparison"><div><span>模板</span><span>{{f.template_value||'（空白）'}}</span></div><div><span>合同</span><span>{{f.value===null?'未能定位':f.value||'（空白）'}}</span></div></div></td><td><span class="report-badge" :class="f.status">{{labels[f.status]}}</span><p class="report-reason">{{f.reason}}</p></td></tr></tbody></table></div>
    <div v-else-if="tab==='differences'&&rows.length" class="report-differences"><article v-for="(d,i) in visible" :key="(page-1)*pageSize+i"><h3>变化 {{(page-1)*pageSize+i+1}} · {{d.reason}}</h3><div><p><b>模板原文</b>{{d.original}}</p><p><b>上传合同</b>{{d.current}}</p></div></article></div>
    <p v-else class="report-empty">{{tab==='fields'?'没有需处理字段':'未发现固定条款差异'}}</p>
    <nav v-if="rows.length" class="report-pagination" aria-label="报告分页"><span role="status">共 {{rows.length}} 项 · 第 {{page}} / {{pages}} 页</span><div><select v-model.number="pageSize" class="field" aria-label="报告每页条数"><option :value="10">10 项 / 页</option><option :value="20">20 项 / 页</option><option :value="50">50 项 / 页</option></select><button class="button" :disabled="page===1" @click="page--">上一页</button><button class="button" :disabled="page===pages" @click="page++">下一页</button></div></nav>
  </div>
  <div v-if="report.limitations.length" class="report-card report-scope"><h3>未能完整校验的内容</h3><p v-for="(item,i) in report.limitations" :key="i">{{item}}</p></div>
  <p class="report-scope-note">记录编号：{{record.id}} · 结论仅覆盖本次已配置的模板规则；需人工确认和检查不完整的内容不能视为通过。</p>
</section>
</template>
